#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize structured logging. RUST_LOG controls verbosity per module:
    //   RUST_LOG=warn                       → only warnings/errors (default-ish)
    //   RUST_LOG=homun_desktop_gateway=info → gateway info+ (broker/turn/chat lifecycle)
    //   RUST_LOG=homun_desktop_gateway=debug → verbose (per-event broker logging)
    //   RUST_LOG=trace                      → everything (noisy, includes deps)
    // Default when RUST_LOG is unset: warn (so existing eprintln! noise is reduced
    // and the user sees real problems). Existing eprintln!/println! calls still
    // print (they bypass tracing) but the structured tracing events are filterable.
    let _ = tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("warn")),
        )
        .with_target(false)
        .try_init();
    // P0 observability: leave a trail for every panic, even when the shell
    // isn't capturing stdio. Fall back to the OS temp dir if HOME is unusable.
    panic_log::install(gateway_logs_dir().unwrap_or_else(|_| std::env::temp_dir()));

    // SECURITY (data at rest): make everything this process writes owner-only.
    // The personal stores (memory.sqlite, desktop-gateway.sqlite, the WhatsApp
    // session, …) are PLAINTEXT SQLite — 0644 would expose the user's memory,
    // contacts and messages to any other local user. umask 0077 makes new files
    // born 0600, including the SQLite WAL/SHM that SQLite creates at runtime.
    #[cfg(unix)]
    // SAFETY: libc::umask has no preconditions; called once before any file is created.
    unsafe {
        libc::umask(0o077 as libc::mode_t);
    }

    // Move any pre-rename data dir to the new ~/.homun location before anything
    // opens it (the SQLite stores are created immediately below).
    gateway_legacy_data::migrate_legacy_data_dir();

    // P0 resilience: verify every personal store BEFORE anything opens it; a
    // corrupt file is quarantined (never deleted) and the fresh open below
    // succeeds. Surfaced to the UI via /api/health `recovered_stores`.
    let recovered_stores: std::sync::Arc<Vec<String>> =
        std::sync::Arc::new(gateway_store_integrity::ensure_gateway_store_integrity()?);

    let addr = gateway_bind::gateway_bind_addr();
    gateway_db_unify::unify_legacy_databases_at_startup()?;
    // Unified WS registry: build the Arc once, register it process-wide (so free
    // functions like `publish_app_event` can publish without `&AppState`), then
    // hand the same Arc to AppState. Clones below are cheap Arc clones.
    let ws_registry_arc = std::sync::Arc::new(ws_gateway::WsRegistry::new());
    let _ = ws_registry().set(ws_registry_arc.clone());
    let usage_path = gateway_database_path()?;
    let usage_store = usage_store::UsageStore::open(&usage_path).map_err(std::io::Error::other)?;
    usage_store
        .abort_orphaned_attempts(i64::try_from(now_epoch_secs()).unwrap_or(i64::MAX))
        .map_err(std::io::Error::other)?;
    usage_store
        .rebuild_daily_rollups()
        .map_err(std::io::Error::other)?;
    let buffered_usage_recorder: Arc<dyn local_first_inference_usage::UsageRecorder> = Arc::new(
        usage_store::BufferedUsageRecorder::start(&usage_path, 4_096)
            .map_err(std::io::Error::other)?,
    );
    let usage_pricing = Arc::new(std::sync::RwLock::new(build_usage_pricing_snapshot(
        &usage_store,
    )));
    let usage_recorder: Arc<dyn local_first_inference_usage::UsageRecorder> =
        Arc::new(usage_pricing::CostEnrichingUsageRecorder::new(
            buffered_usage_recorder,
            usage_pricing.clone(),
        ));
    let _ = usage_recorder_registry().set(usage_recorder.clone());
    let mut state = AppState {
        http: gateway_http_client::build_gateway_http_client(),
        usage_store: Arc::new(Mutex::new(usage_store)),
        usage_recorder,
        usage_pricing,
        chat_store: Arc::new(Mutex::new(ChatStore::open(gateway_database_path()?)?)),
        task_store: Arc::new(Mutex::new(TaskStore::open(gateway_task_database_path()?)?)),
        computer_store: Arc::new(Mutex::new(LocalComputerSessionStore::open(
            gateway_local_computer_database_path()?,
        )?)),
        browser_url_policies: Arc::new(Mutex::new(BrowserUrlPolicyStore::open(
            gateway_browser_policy_database_path()?,
        )?)),
        memory_facade: Arc::new(MemoryFacade::new(
            SQLiteMemoryStore::open(gateway_memory_database_path()?)
                .map_err(std::io::Error::other)?,
        )),
        // ADR 0022 (Tappa 1): costruisci il service solo se il flag è ON.
        // L'impl delega interamente alla memoria_facade sopra (condivisa via Arc),
        // quindi niente nuovi store, niente big-bang.
        memory_service: None,
        vault_store: Arc::new(Mutex::new(
            SQLiteVaultStore::open(gateway_vault_database_path()?)
                .map_err(std::io::Error::other)?,
        )),
        vault_wrap_key: Arc::new(gateway_vault_key::resolve_vault_wrap_key()?),
        pending_vault_proposals: Arc::new(privacy_guard::PendingVaultProposalStore::default()),
        capability_registry: Arc::new(Mutex::new(open_seeded_capability_registry()?)),
        task_executor_status: Arc::new(Mutex::new(TaskExecutorStatus::new(
            gateway_task_executor_config::task_executor_worker_enabled(),
        ))),
        task_executor_registry: ExecutionRuntime::default_registry(),
        browser_capability_client: Arc::new(Mutex::new(None)),
        browser_thread_sessions: Arc::new(Mutex::new(std::collections::HashMap::new())),
        hitl_resume_by_thread: Arc::new(Mutex::new(std::collections::HashMap::new())),
        payment_approvals: Arc::new(Mutex::new(std::collections::HashMap::new())),
        setup_computer: Arc::new(setup_computer::SetupComputerCoordinator::default()),
        secret_store: Arc::new(gateway_secrets::open_gateway_secret_store()?),
        browser_checkpoint_secret_store: Arc::new(open_browser_checkpoint_secret_store()?),
        auth_token: gateway_auth::resolve_gateway_auth_token(
            &gateway_paths::gateway_data_dir()?,
            gateway_file_security::write_private_file,
        )?
        .into(),
        novnc_tickets: Arc::new(Mutex::new(std::collections::HashMap::new())),
        novnc_view_ticket: Arc::new(Mutex::new(None)),
        ws_registry: ws_registry_arc,
        recovered_stores: recovered_stores.clone(),
    };
    migrate_legacy_mcp_http_header_secrets(&state)
        .map_err(|error| std::io::Error::other(error.message))?;
    // ADR 0022 — Tappa 1: se il flag è ON, costruisci il service memoria che
    // incapsula brief/recall/learn. Costruito dopo il letterale perché
    // `InProcessMemoryRecallService` prende in prestito lo stesso `AppState`.
    let embedding: Arc<dyn local_first_memory::EmbeddingClient> =
        gateway_embedding_client(state.http.clone());
    let llm: Arc<dyn local_first_memory::LlmClient> = gateway_llm_client(state.http.clone());
    install_memory_service_if_enabled(&mut state, embedding, llm);
    // Fix any pre-existing 0644 data files (created before the umask above was set):
    // the SQLite stores and the WhatsApp session are world-readable on old installs.
    if let Ok(dir) = gateway_data_dir() {
        gateway_file_security::harden_data_at_rest(&dir);
    }
    gateway_boot_maintenance::run_gateway_boot_maintenance(&state);
    gateway_turn_recovery::recover_gateway_chat_turns_at_startup(&state).await;
    gateway_background_startup::start_gateway_background_services(state.clone());
    let startup_state = state.clone();
    let app = gateway_routes::build_gateway_router(state.clone());
    // Warm up the contained computer so the live view + browser are ready without waiting for
    // the first skill. Off the async runtime so startup is not blocked by the container boot.
    // Behavior depends on the user's `local_computer_autostart` setting (default ON):
    //   ON  → start it eagerly, OPENING Docker if it's closed (ensure_contained_computer).
    //   OFF → stay non-intrusive: only warm up when Docker is already running.
    let computer_warmup_state = startup_state.clone();
    tokio::spawn(async move {
        if sandbox::container_up() {
            return;
        }
        let autostart = load_runtime_settings().local_computer_autostart;
        if autostart || sandbox::docker_running() {
            let _ = begin_setup_computer(computer_warmup_state).await;
        }
    });
    let listener = TcpListener::bind(addr).await?;
    println!("local-first-desktop-gateway listening on http://{addr}");
    tokio::spawn(reconnect_channels_on_startup(startup_state));
    axum::serve(listener, app).await?;
    Ok(())
}

/// Auto-confirm policy (M2): only durable, high-confidence knowledge enters memory
/// without asking. The ceiling is `Private` — NOT `Internal` — on purpose: the
/// extractor tags ordinary personal facts (possessions, family, city) as `private`
/// by its own rules, so an `Internal` cap froze EVERY personal fact at `candidate`,
/// invisible to the always-on profile (which is confirmed-only). A personal
/// assistant must know what you own / who's in your life without re-asking, so
/// `private` auto-confirms. Only `Confidential`/`Secret` (real PII — codice fiscale,
/// health docs, addresses) stays a candidate for the user to confirm explicitly.
#[cfg(test)]
fn is_auto_confirmable(
    memory_type: &str,
    sensitivity: MemoryDataSensitivity,
    confidence: f64,
) -> bool {
    // Decisions are factual records of choices made during work (low privacy risk),
    // so they auto-confirm like facts/preferences when confident + non-sensitive.
    matches!(
        memory_type,
        "preference" | "fact" | "decision" | "goal" | "open_loop"
    ) && sensitivity <= MemoryDataSensitivity::Private
        && confidence >= 0.8
}

/// Strip a ```json … ``` fence the model may wrap JSON in.
fn strip_json_fences(text: &str) -> &str {
    let trimmed = text.trim();
    let without_open = trimmed
        .strip_prefix("```json")
        .or_else(|| trimmed.strip_prefix("```"))
        .unwrap_or(trimmed);
    without_open
        .trim()
        .strip_suffix("```")
        .unwrap_or(without_open.trim())
        .trim()
}

// ---- Embeddings (multilingual semantic layer) -----------------------------------
// A multilingual embedding model (nomic-embed-text-v2-moe by default, via the local
// Ollama) gives language-agnostic SEMANTIC similarity — fuses paraphrases of the same
// decision (and across languages) for dedup, and powers semantic recall. Vectors are
// stored per memory; similarity is brute-force cosine (fine at local single-user scale).

fn embed_model() -> String {
    env::var("HOMUN_EMBED_MODEL").unwrap_or_else(|_| "nomic-embed-text-v2-moe".to_string())
}
fn embed_base() -> String {
    env::var("HOMUN_EMBED_BASE").unwrap_or_else(|_| "http://127.0.0.1:11434".to_string())
}

fn inference_locality(base_url: &str) -> local_first_inference_usage::Locality {
    if base_url.contains("127.0.0.1") || base_url.contains("localhost") {
        local_first_inference_usage::Locality::Local
    } else {
        local_first_inference_usage::Locality::Cloud
    }
}

fn inference_provider_id(base_url: &str) -> String {
    let canonical = canonical_provider_base_url(base_url);
    if let Some(provider) = load_provider_registry()
        .providers
        .into_iter()
        .find(|provider| canonical_provider_base_url(&provider.base_url) == canonical)
    {
        return provider.id;
    }
    let lower = canonical.to_ascii_lowercase();
    if lower.contains("anthropic.com") {
        "anthropic".to_string()
    } else if lower.contains("ollama.com") || provider_endpoint_is_local(&canonical) {
        "ollama".to_string()
    } else if lower.contains("openai.com") {
        "openai".to_string()
    } else if lower.contains("openrouter.ai") {
        "openrouter".to_string()
    } else if lower.contains("z.ai") {
        "zai".to_string()
    } else {
        "openai-compatible".to_string()
    }
}

#[allow(clippy::too_many_arguments)]
async fn recorded_openai_value(
    http: &reqwest::Client,
    base_url: &str,
    model: &str,
    api_key: Option<&str>,
    payload: &serde_json::Value,
    timeout: std::time::Duration,
    purpose: local_first_inference_usage::InferencePurpose,
    detail: &str,
    estimated_input_chars: usize,
) -> Option<inference_transport::RecordedJsonResponse> {
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        purpose,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some(detail.to_string());
    usage.workspace_id = Some(gateway_workspace_id().as_str().to_string());
    inference_transport::send_openai_json(
        http,
        global_usage_recorder(),
        &usage,
        &inference_provider_id(base_url),
        model,
        inference_locality(base_url),
        base_url,
        api_key,
        payload,
        Some(timeout),
        estimated_input_chars,
    )
    .await
    .ok()
}

/// Embed one text via Ollama `/api/embed`. Best-effort: `None` on any failure (the
/// caller falls back to lexical), so embeddings never break a turn.
async fn embed_text(
    http: &reqwest::Client,
    text: &str,
    usage: &local_first_inference_usage::UsageContext,
) -> Option<Vec<f32>> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return None;
    }
    let response = inference_transport::send_ollama_embed(
        http,
        global_usage_recorder(),
        usage,
        &embed_base(),
        &embed_model(),
        trimmed,
        Some(std::time::Duration::from_secs(30)),
    )
    .await
    .ok()?;
    if !(200..300).contains(&response.status) {
        return None;
    }
    let body = response.body;
    let arr = body
        .get("embeddings")
        .and_then(|e| e.get(0))
        .and_then(|v| v.as_array())
        .cloned()
        .or_else(|| body.get("embedding").and_then(|v| v.as_array()).cloned())?;
    let vector: Vec<f32> = arr
        .iter()
        .filter_map(|x| x.as_f64().map(|f| f as f32))
        .collect();
    (!vector.is_empty()).then_some(vector)
}

/// Local Ollama OpenAI-compat base for image generation (the last-resort default).
fn default_image_base() -> String {
    let ollama =
        std::env::var("HOMUN_EMBED_BASE").unwrap_or_else(|_| "http://127.0.0.1:11434".to_string());
    format!("{}/v1", ollama.trim_end_matches('/'))
}

/// API key from the `HOMUN_IMAGE_KEY` env, if non-empty.
fn image_env_key() -> Option<String> {
    std::env::var("HOMUN_IMAGE_KEY")
        .ok()
        .filter(|s| !s.trim().is_empty())
}

/// Image-generation provider config: (base_url, model, api_key). Provider-agnostic and
/// OpenAI-compatible (`{base}/images/generations`), so the SAME path serves LOCAL Ollama
/// (Flux / Z-Image, via MLX) AND cloud diffusion (Gemini "Nano Banana", OpenAI gpt-image,
/// fal, …).
///
/// Resolution order (WordPress-style: the plugin declares the capability, the core's
/// "Model per task" config drives it):
///   1. Manual pin of the `image_generation` role (Settings → Runtime → Model per task).
///   2. Explicit env override (HOMUN_IMAGE_BASE / _MODEL / _KEY) — operator/deploy.
///   3. Auto-matched image model from the provider catalog (a real "image"-modality model).
///   4. Local Ollama `z-image` default.
///
/// NB: we never let the role auto-matcher's text-model fallback through for images — a
/// chat model can't draw — so step 3 is gated on an actual image model being eligible.
fn image_provider_config() -> (String, String, Option<String>) {
    let registry = load_provider_registry();

    // 1) Manual pin — trusted even if the catalog wasn't refreshed (e.g. a cloud
    //    image-model id typed by hand).
    if let Some((provider_id, model)) = registry.manual_binding("image_generation")
        && let Some(provider) = registry.get(&provider_id)
    {
        let key = provider_api_key(&provider_id).or_else(image_env_key);
        return (provider.base_url.clone(), model, key);
    }

    // 2) Explicit env override.
    let env_base = std::env::var("HOMUN_IMAGE_BASE")
        .ok()
        .filter(|s| !s.trim().is_empty());
    let env_model = std::env::var("HOMUN_IMAGE_MODEL")
        .ok()
        .filter(|s| !s.trim().is_empty());
    if env_base.is_some() || env_model.is_some() {
        return (
            env_base.unwrap_or_else(default_image_base),
            env_model.unwrap_or_else(|| "z-image".to_string()),
            image_env_key(),
        );
    }

    // 3) Auto-matched image model from the catalog (only when one truly exists).
    if !registry.eligible_models("image_generation").is_empty()
        && let Some(resolved) = registry.resolve_role("image_generation")
    {
        let key = provider_api_key(&resolved.provider_id).or_else(image_env_key);
        return (resolved.base_url, resolved.model, key);
    }

    // 4) Local Ollama image default.
    (default_image_base(), "z-image".to_string(), None)
}

/// Generate a PNG from a text prompt via the configured image provider (local Ollama or
/// cloud). Returns raw PNG bytes. Best-effort across the two common response shapes
/// (`data[0].b64_json` and `data[0].url`).
/// Per-request timeout for image generation. Default 300s (5 min): a LOCAL diffusion
/// model on a cold start (model load + first sampling) can easily exceed the old 180s
/// and get killed mid-generation even though it would have succeeded. Override with
/// `HOMUN_IMAGE_TIMEOUT_SECS` (e.g. a slow CPU-only box, or a very large model).
fn image_timeout_secs() -> u64 {
    std::env::var("HOMUN_IMAGE_TIMEOUT_SECS")
        .ok()
        .and_then(|s| s.trim().parse::<u64>().ok())
        .filter(|&s| s > 0)
        .unwrap_or(300)
}

fn deck_slide_image_prompt(title: &str, accent: &str) -> String {
    let topics = title
        .split_whitespace()
        .filter_map(|word| {
            let clean = word
                .chars()
                .filter(|ch| ch.is_ascii_alphabetic() || *ch == '-')
                .collect::<String>()
                .trim_matches('-')
                .to_ascii_lowercase();
            if clean.len() < 3 { None } else { Some(clean) }
        })
        .take(5)
        .collect::<Vec<_>>();
    let topic_line = if topics.is_empty() {
        "an abstract product narrative".to_string()
    } else {
        format!("themes: {}", topics.join(", "))
    };

    format!(
        "Editorial, modern, professional slide illustration about {topic_line}. \
Clean minimal composition, {accent} accents, abstract shapes, subtle depth, lots of negative space. \
No typography of any kind: no readable text, words, letters, numbers, captions, labels, UI screenshots or logos. \
Do not render the topic words as visible text."
    )
}

async fn generate_image_png(
    http: &reqwest::Client,
    prompt: &str,
    size: &str,
) -> Result<Vec<u8>, String> {
    let (base, model, key) = image_provider_config();
    let endpoint = format!("{}/images/generations", base.trim_end_matches('/'));
    let mut builder = http
        .post(&endpoint)
        .timeout(std::time::Duration::from_secs(image_timeout_secs()))
        .json(&serde_json::json!({
            "model": model,
            "prompt": prompt,
            "n": 1,
            "size": size,
            "response_format": "b64_json",
        }));
    if let Some(key) = key.as_ref() {
        builder = builder.bearer_auth(key);
    }
    let resp = builder
        .send()
        .await
        .map_err(|e| format!("image provider unreachable ({endpoint}): {e}"))?;
    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!(
            "image provider HTTP {status}: {}. Check the image model is available (e.g. `ollama pull {model}`) or set a cloud provider via HOMUN_IMAGE_BASE/MODEL/KEY.",
            body.chars().take(180).collect::<String>()
        ));
    }
    let json: serde_json::Value = resp
        .json()
        .await
        .map_err(|e| format!("bad image response: {e}"))?;
    let data = json
        .get("data")
        .and_then(|d| d.as_array())
        .and_then(|a| a.first());
    if let Some(b64) = data
        .and_then(|d| d.get("b64_json"))
        .and_then(|v| v.as_str())
    {
        return base64::engine::general_purpose::STANDARD
            .decode(b64.as_bytes())
            .map_err(|e| format!("image decode failed: {e}"));
    }
    if let Some(url) = data.and_then(|d| d.get("url")).and_then(|v| v.as_str()) {
        let bytes = http
            .get(url)
            .send()
            .await
            .map_err(|e| format!("image url fetch failed: {e}"))?
            .bytes()
            .await
            .map_err(|e| format!("image url read failed: {e}"))?;
        return Ok(bytes.to_vec());
    }
    Err("image provider returned no image data".to_string())
}

/// Embed memories in a scope that don't yet have a vector (lazy backfill). Collects
/// refs+texts under the lock, embeds OFF the lock (async HTTP), writes back. Bounded
/// per call so it never stalls a turn.
async fn backfill_embeddings(
    state: &AppState,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    limit: usize,
) {
    // ADR 0022 (Tappa 4): backfill ORCHESTRATO nel crate via 3 fasi Send-safe
    // (collect lock → embed off-lock → persist lock). Il guard non attraversa await.
    let embedding: std::sync::Arc<dyn local_first_memory::EmbeddingClient> =
        gateway_embedding_client(state.http.clone());
    let model = embed_model();
    // Fase 1 (lock): collect pending + seen.
    let collected = {
        let facade = memory_facade(state);
        local_first_memory::backfill_collect_pending(facade, user, workspace, limit)
    };
    let Some((pending, mut seen)) = collected else {
        return;
    };
    // Fase 2 + 3: embed off-lock, poi persist sotto lock per ciascuno.
    for (reference, text, mtype) in pending {
        let vector = embedding.embed(&text).await;
        if vector.is_empty() {
            continue;
        }
        {
            let facade = memory_facade(state);
            local_first_memory::backfill_persist_one(
                facade, user, workspace, &reference, &mtype, &vector, &model, &mut seen,
            );
        }
    }
}

/// Reserved workspace for THREAD (episodic) memory — "what we discussed". Kept
/// out of the personal/project scopes so episodes never flood the always-on
/// profile or the management list; reached only via recall.
const THREADS_WORKSPACE: &str = "__threads__";

/// M4: store a one-line episodic summary of a conversation turn, tagged with its
/// thread, in the thread scope. Confirmed directly (a factual record), retrievable
/// later via recall ("cosa dicevamo l'altra volta").
fn store_episode(
    facade: &MemoryFacade,
    user_id: &MemoryUserId,
    thread_id: &str,
    summary: &str,
    origin_workspace: &str,
) {
    let summary = summary.trim();
    if summary.is_empty() {
        return;
    }
    let workspace = MemoryWorkspaceId::new(THREADS_WORKSPACE);
    let extracted = ExtractedMemory {
        memory_type: "episode".to_string(),
        text: summary.to_string(),
        aliases: Vec::new(),
        language_hints: Vec::new(),
        confidence: 1.0,
        privacy_domain: PrivacyDomain::new("personal"),
        sensitivity: MemoryDataSensitivity::Internal,
        evidence_refs: Vec::new(),
        evolution: None,
        // `workspace` = the scope this conversation belongs to, so episodic recall can be
        // ISOLATED per project (a project recalls only its own conversations, not personal).
        metadata: serde_json::json!({ "thread_id": thread_id, "scope": "thread", "workspace": origin_workspace }),
    };
    let extraction = MemoryExtraction {
        memories: vec![extracted],
        entities: Vec::new(),
        relations: Vec::new(),
    };
    let Ok(result) = facade.apply_extraction(user_id, &workspace, extraction) else {
        return;
    };
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "memory-extractor".to_string(),
        user_id: user_id.clone(),
        workspace_id: workspace,
        purpose: "episode".to_string(),
    };
    if let Some(reference) = result.memory_refs.first() {
        let _ = facade.confirm_memory(&lifecycle, reference, "episode");
    }
}

fn current_thread_episode_block(state: &AppState, thread_id: &str) -> Option<String> {
    let user = gateway_memory_user_id();
    let threads = MemoryWorkspaceId::new(THREADS_WORKSPACE);
    let origin_workspace = gateway_memory_workspace_id();
    let mut episodes = memory_facade(state)
        .list_memories_for_ui(&user, &threads)
        .ok()?
        .into_iter()
        .filter(|memory| memory.status == MemoryStatus::Confirmed)
        .filter(|memory| {
            episode_metadata_matches_scope(&memory.metadata, thread_id, origin_workspace.as_str())
        })
        .collect::<Vec<_>>();
    episodes.sort_by(|left, right| left.updated_at.cmp(&right.updated_at));
    let mut selected = Vec::new();
    let mut used = 0usize;
    for episode in episodes.into_iter().rev().take(24) {
        if used.saturating_add(episode.text.len()) > CHAT_MEMORY_BUDGET_CHARS / 2 {
            break;
        }
        used += episode.text.len();
        selected.push(episode.text);
    }
    if selected.is_empty() {
        return None;
    }
    selected.reverse();
    Some(format!(
        "CURRENT THREAD MEMORY (confirmed episodes from this exact thread and workspace):\n- {}",
        selected.join("\n- ")
    ))
}

fn episode_metadata_matches_scope(
    metadata: &serde_json::Value,
    thread_id: &str,
    workspace_id: &str,
) -> bool {
    metadata.get("thread_id").and_then(|value| value.as_str()) == Some(thread_id)
        && metadata.get("workspace").and_then(|value| value.as_str()) == Some(workspace_id)
}

/// ADR 0022 — Tappa 1: apprendimento post-turno. Quando `HOMUN_MEMORY_SERVICE=on`
/// ADR 0022 — Tappa 1/4: apprendimento post-turno. Quando il service è ON
/// (`HOMUN_MEMORY_SERVICE`) instrada via `MemoryRecallService::learn`; anche nel
/// path OFF usa le STESSE fn del crate (3 fasi: prepare_learn_prompt →
/// LlmClient.chat → persist_learn_extraction) con capability client costruiti
/// al volo — così `learn_from_exchange` non è più duplicata nel gateway.
#[allow(clippy::too_many_arguments)]
fn learn_via_service_or_inline(
    state: &AppState,
    user_message: &str,
    assistant_message: &str,
    actions: &str,
    thread_id: Option<&str>,
    turn_id: Option<&str>,
    speaker: Option<&str>,
    prev_assistant: Option<&str>,
    reuse_envelope: local_first_memory::MemoryReuseEnvelope,
) -> local_first_memory::BoxFuture<'static, ()> {
    if let Some(service) = state.memory_service.clone() {
        let scope = scope_from_active_workspace();
        let exchange = Exchange {
            user_message: user_message.to_string(),
            assistant_message: assistant_message.to_string(),
            actions: actions.to_string(),
            thread_id: thread_id.map(str::to_string),
            turn_id: turn_id.map(str::to_string),
            speaker: speaker.map(str::to_string),
            prev_assistant: prev_assistant.map(str::to_string),
            reuse_envelope,
        };
        Box::pin(async move { service.learn(&exchange, &scope).await })
    } else {
        // Path OFF: stessa orchestrazione del crate, capability client al volo.
        let state = state.clone();
        let user_message = user_message.to_string();
        let assistant_message = assistant_message.to_string();
        let actions = actions.to_string();
        let thread_id = thread_id.map(str::to_string);
        let turn_id = turn_id.map(str::to_string);
        let speaker = speaker.map(str::to_string);
        let prev_assistant = prev_assistant.map(str::to_string);
        let exchange = Exchange {
            user_message,
            assistant_message,
            actions,
            thread_id: thread_id.clone(),
            turn_id,
            speaker,
            prev_assistant,
            reuse_envelope,
        };
        Box::pin(async move {
            let user = gateway_memory_user_id();
            let active = gateway_memory_workspace_id();
            let project_name = if active.as_str() != PERSONAL_WORKSPACE {
                load_workspaces_file()
                    .workspaces
                    .into_iter()
                    .find(|w| w.id.as_str() == active.as_str())
                    .map(|w| w.name)
            } else {
                None
            };
            let llm: std::sync::Arc<dyn local_first_memory::LlmClient> =
                gateway_llm_client(state.http.clone());
            // Fase 1 (lock): prompt.
            let prompt = {
                let facade = memory_facade(&state);
                local_first_memory::prepare_learn_prompt(
                    facade,
                    &user,
                    &active,
                    &exchange,
                    project_name.as_deref(),
                )
            };
            let Some((system, user_content)) = prompt else {
                return;
            };
            // Fase 2 (off-lock): LLM.
            let Some(content) = llm.chat(&system, &user_content).await else {
                return;
            };
            // Fase 3 (lock): persist + hooks.
            let facade = memory_facade(&state);
            let hooks = local_first_memory::LearnHooks {
                persist_graph: Some(
                    &|facade, user, workspace, entities, relations, project_ws| {
                        persist_graph(facade, user, workspace, entities, relations, project_ws);
                    },
                ),
                store_episode: Some(&|facade, user, thread_id, episode, active| {
                    store_episode(facade, user, thread_id, episode, active);
                }),
                backfill_embeddings: None,
            };
            local_first_memory::persist_learn_extraction(
                facade, &user, &active, &content, &exchange, hooks,
            );
        })
    }
}
async fn call_memory_json(
    state: &AppState,
    system: &str,
    user_content: &str,
) -> Option<serde_json::Value> {
    let (base_url, model, api_key) = extractor_openai_config()?;
    let payload = serde_json::json!({
        "model": model,
        "temperature": 0.0,
        "max_tokens": 4000,
        "response_format": { "type": "json_object" },
        "messages": [
            { "role": "system", "content": system },
            { "role": "user", "content": user_content },
        ],
    });
    let mut usage = local_first_inference_usage::UsageContext::new(
        uuid::Uuid::new_v4().to_string(),
        local_first_inference_usage::InferencePurpose::MemoryExtraction,
        gateway_user_id().as_str(),
    );
    usage.purpose_detail = Some("memory_json".to_string());
    usage.workspace_id = Some(gateway_memory_workspace_id().as_str().to_string());
    let response = inference_transport::send_openai_json(
        &state.http,
        state.usage_recorder.clone(),
        &usage,
        &inference_provider_id(&base_url),
        &model,
        inference_locality(&base_url),
        &base_url,
        api_key.as_deref(),
        &payload,
        Some(std::time::Duration::from_secs(150)),
        system
            .chars()
            .count()
            .saturating_add(user_content.chars().count()),
    )
    .await
    .ok()?;
    if !(200..300).contains(&response.status) {
        return None;
    }
    let body = response.body;
    let content = body
        .get("choices")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("message"))
        .and_then(|m| m.get("content"))
        .and_then(|c| c.as_str())?;
    serde_json::from_str(strip_json_fences(content)).ok()
}

/// Memory consolidation ("reflection"): review a scope's durable memories, MERGE the
/// fragments that say the same thing, and PRUNE noise (transient/trivial/irrelevant or
/// redundant). Conservative — when in doubt the model keeps. Returns (merged, dropped).
///
/// ADR 0022 (Tappa 4, F3): orchestrazione migrata nel crate via 3 fasi Send-safe
/// (`consolidate_prepare` → LLM curatore off-lock → `consolidate_apply`). Il
/// `MutexGuard` non attraversa l'await della LLM call. Corpo spostato fedelmente.
async fn consolidate_scope(
    state: &AppState,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
) -> (usize, usize) {
    // is_edited callback: il crate non legge il FS gateway (pattern = hooks).
    let is_edited = |ws: &MemoryWorkspaceId, path: &str| wiki_is_edited(ws, path);
    // Fase 1 (lock): dedup open-loop + pre-pass deterministico + listing.
    let (merged, prepared) = {
        let facade = memory_facade(state);
        local_first_memory::consolidate_prepare(facade, user, workspace, &is_edited)
    };
    let Some(input) = prepared else {
        // <3 memorie sopravvissute (o early-exit): wiki già ricostruite nella prepare.
        return (merged, 0);
    };
    // Fase 2 (off-lock): LLM curatore via client gateway throwaway, poi parse
    // JSON resiliente (strip_json_fences è nel crate).
    let llm: std::sync::Arc<dyn local_first_memory::LlmClient> =
        gateway_llm_client(state.http.clone());
    let content = llm
        .chat(
            local_first_memory::CURATOR_SYSTEM,
            &format!("MEMORIE ATTUALI:\n{}", input.listing),
        )
        .await;
    let root = content.and_then(|c| {
        serde_json::from_str::<serde_json::Value>(local_first_memory::strip_json_fences(&c)).ok()
    });
    let Some(root) = root else {
        // LLM curator unavailable: keep the deterministic merges already applied,
        // rebuild the wiki pages.
        {
            let facade = memory_facade(state);
            local_first_memory::rebuild_all_wiki(facade, user, workspace, &is_edited);
        }
        return (merged, 0);
    };
    // Fase 3 (lock re-acquisito): applica merge/drop + ricostruisce wiki.
    let facade = memory_facade(state);
    local_first_memory::consolidate_apply(
        facade,
        user,
        workspace,
        &root,
        &input.mems,
        merged,
        &is_edited,
        &|text| redact_sensitive_text(text),
    )
}

fn tombstone_automation_memory_records(
    facade: &MemoryFacade,
    user: &MemoryUserId,
    workspace: &MemoryWorkspaceId,
    automation_id: &str,
) -> Result<usize, String> {
    let lifecycle = MemoryLifecycleRequest {
        actor_id: "automation".to_string(),
        user_id: user.clone(),
        workspace_id: workspace.clone(),
        purpose: "automation_removed".to_string(),
    };
    let mut deleted = 0;
    for memory in facade
        .list_memories_for_ui(user, workspace)
        .map_err(|error| error.to_string())?
    {
        let matches_id = memory
            .metadata
            .get("automation_id")
            .and_then(|value| value.as_str())
            == Some(automation_id);
        if !matches_id {
            continue;
        }
        facade
            .delete_memory(&lifecycle, &memory.reference, "automation deleted")
            .map_err(|error| error.to_string())?;
        deleted += 1;
    }
    Ok(deleted)
}

// `answer_body_is_empty` folded into `local_first_engine::markers::
// should_force_synthesis_for_empty_visible_answer` (5.D1c) — the empty-answer check now lives with the
// stripper it depends on, in the engine.

/// The plan steps reconciled for delivery: EVERY still-open step forced to `done`, `blocked`
/// preserved. Returns `Some` only when reconciliation is enabled, a substantial answer was
/// delivered, and something actually changed — otherwise `None` (nothing to reconcile).
///
/// This is the single source of truth shared by the displayed ‹‹PLAN›› marker AND the
/// persisted runtime plan, so the two can never diverge (a text-only reconcile would show
/// the user 7/7 while the durable plan stays at 3/7, leaving the NEXT turn to falsely resume
/// an already-delivered plan).
///
/// It runs ONLY on the delivery path (25127/25242) — after the round loop has already DECIDED
/// to stop (nudges spent, round budget hit, or the model concluded). At that instant nothing
/// is "in progress" anymore, so a substantial final answer means the plan's work is delivered.
/// Models routinely answer the whole request but stop calling `step_advance` for the tail
/// (deepseek delivered all 7 markets yet left the plan frozen at 3/7 with a phantom "active"
/// step — the "non so a che punto è arrivato" symptom). `blocked` stays blocked: it's an
/// explicit failure the model recorded, not something to launder into success. The char floor
/// guards the genuinely-truncated case (budget burned, empty/short answer). NOTE: deliberately
/// does NOT reuse `answer_concludes_plan` — that predicate must stay conservative for the
/// *nudge* decision (25001), where many open steps means "keep pushing", the opposite intent.
fn plan_steps_reconciled_on_delivery(
    _plan: &ExecutionPlan,
    _text: &str,
) -> Option<Vec<serde_json::Value>> {
    // Completion is evidence-driven (`step_advance` + done criteria). Delivery
    // length is never proof that open work happened: the old sweep converted
    // every open step to done after a long answer and laundered partial runs.
    None
}

/// Thin text-only wrapper over `plan_steps_reconciled_on_delivery` — the delivery call sites
/// need the reconciled steps to ALSO persist the runtime plan, so they use the helper directly;
/// this convenience form (marker replacement only) is kept for the delivery-reconcile tests.
#[cfg(test)]
fn reconcile_final_plan_marker_on_delivery(plan: &ExecutionPlan, text: &str) -> String {
    match plan_steps_reconciled_on_delivery(plan, text) {
        Some(plan_steps) => replace_latest_plan_marker(text, &plan_steps),
        None => text.to_string(),
    }
}

fn plan_step_depends_on(step: &serde_json::Value) -> Vec<String> {
    step.get("depends_on")
        .and_then(|value| value.as_array())
        .into_iter()
        .flatten()
        .filter_map(|value| value.as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect()
}

// --- F4: cross-turn plan-stall guard -------------------------------------------------
//
// The per-turn recovery counters (nav-fail `nav_failures`, round budget
// `rounds_since_progress`) are reset every turn. A plan RESUMED across turns
// (`load_runtime_plan_from_state`, channel/resume) therefore restarts its current step with
// the counters at zero — so a step that fails deterministically (dead URL, unfillable form)
// retries forever, once per resume. The fix is a CROSS-turn signal: count consecutive resumes
// that close NO new step; after the cap the harness blocks the stuck step (caposaldo #2 — the
// harness owns recovery, the model won't pivot on its own). The pure pieces live here, tested.

/// Max consecutive resumes of a plan with no new completed step before the harness blocks the
/// stuck step. Generous on purpose: a plan legitimately advancing even one step per turn never
/// trips (any `done`-count increase resets the counter); only genuine no-progress loops do.
const MAX_PLAN_STALL_RESUMES: u32 = 3;

/// New stall count from the prior count and the done-counts at the previous vs the current
/// resume. ANY progress (more done steps than last resume) resets to 0; otherwise +1. Pure.
#[cfg(test)]
fn next_plan_stall(prior_stall: u32, last_resume_done: usize, current_done: usize) -> u32 {
    if current_done > last_resume_done {
        0
    } else {
        prior_stall.saturating_add(1)
    }
}

fn plan_stall_exhausted(stall: u32) -> bool {
    stall >= MAX_PLAN_STALL_RESUMES
}

/// Block the first runnable (`todo`/`doing`) step — the F4 abort action once a plan has
/// stalled across resumes. Records WHY in the step's `detail` (surfaced in the Plan panel).
/// Returns the blocked step's title, or None if nothing was runnable. Pure (mutates `plan`).
fn block_stalled_step(plan: &mut [serde_json::Value]) -> Option<String> {
    for step in plan.iter_mut() {
        if matches!(plan_step_status(step), "todo" | "doing") {
            let title = plan_step_title(step).to_string();
            step["status"] = serde_json::json!("blocked");
            step["detail"] = serde_json::json!(format!(
                "paused by the harness: no progress after {MAX_PLAN_STALL_RESUMES} resumed turns"
            ));
            return Some(title).filter(|t| !t.is_empty());
        }
    }
    None
}

// `MIN_DELIVERED_CHARS_TO_CONCLUDE` + `answer_concludes_plan` moved to `engine::plan`
// (ADR 0024 inc 5e.3); imported below.

fn runtime_plan_thread_key(thread_id: Option<&str>) -> String {
    thread_id
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .unwrap_or("__no_thread__")
        .to_string()
}

fn runtime_plan_control_scope(
    state: &AppState,
    thread_id: Option<&str>,
) -> Option<(String, String, String)> {
    let thread_id = runtime_plan_thread_key(thread_id);
    let workspace_id = if thread_id == "__no_thread__" {
        gateway_workspace_id().as_str().to_string()
    } else {
        state
            .chat_store
            .lock()
            .ok()?
            .workspace_for_thread(&thread_id)
            .ok()?
    };
    Some((
        gateway_user_id().as_str().to_string(),
        workspace_id,
        thread_id,
    ))
}

fn read_project_instruction(root: &std::path::Path, relative: &str) -> Option<String> {
    const MAX_PROJECT_INSTRUCTION_CHARS: usize = 32 * 1024;
    let root = root.canonicalize().ok()?;
    let path = root.join(relative).canonicalize().ok()?;
    if !path.starts_with(&root) || !path.is_file() {
        return None;
    }
    let text = std::fs::read_to_string(path).ok()?;
    Some(text.chars().take(MAX_PROJECT_INSTRUCTION_CHARS).collect())
}

fn compose_gateway_prompt_packets(
    state: &AppState,
    thread_id: Option<&str>,
    core: String,
    workspace: String,
    runtime: String,
) -> (String, Vec<local_first_engine::PromptPacketMetadata>) {
    let mut packets = vec![local_first_engine::PromptPacket {
        id: "homun-core".to_string(),
        source: local_first_engine::PromptPacketSource::Core,
        priority: 10,
        content: core,
    }];
    if !workspace.trim().is_empty() {
        packets.push(local_first_engine::PromptPacket {
            id: "workspace-context".to_string(),
            source: local_first_engine::PromptPacketSource::Workspace,
            priority: 20,
            content: workspace,
        });
    }
    if let Some(root) = project_root_for_thread(state, thread_id) {
        for (id, relative, priority) in [
            ("project-agents", "AGENTS.md", 30),
            ("project-homun", ".homun/instructions.md", 31),
        ] {
            if let Some(content) = read_project_instruction(&root, relative) {
                packets.push(local_first_engine::PromptPacket {
                    id: id.to_string(),
                    source: local_first_engine::PromptPacketSource::Project,
                    priority,
                    content,
                });
            }
        }
    }
    if let Some(thread_id) = thread_id {
        let thread = lock_store(state)
            .ok()
            .and_then(|store| store.thread(thread_id).ok().flatten());
        let binding = active_routing_binding(state, Some(thread_id));
        let mut lines = Vec::new();
        if let Some(source) = thread.and_then(|thread| thread.source) {
            lines.push(format!(
                "THREAD PERIMETER: this conversation originates from the {source} channel; keep its configured contact and permission boundary."
            ));
        }
        if let Some(binding) = binding {
            lines.push(format!(
                "THREAD ROUTING: preserve the explicit plugin route {}/{} until the binding is removed.",
                binding.plugin_id, binding.route_id
            ));
        }
        if !lines.is_empty() {
            packets.push(local_first_engine::PromptPacket {
                id: "thread-context".to_string(),
                source: local_first_engine::PromptPacketSource::Thread,
                priority: 40,
                content: lines.join("\n"),
            });
        }
    }
    packets.push(local_first_engine::PromptPacket {
        id: "runtime-control".to_string(),
        source: local_first_engine::PromptPacketSource::Runtime,
        priority: 100,
        content: format!(
            "{}\n\nRUNTIME CONTROL: preserve verified plan progress, do not repeat an effect whose receipt is uncertain, and obey the currently offered tool surface.",
            runtime.trim()
        ),
    });
    local_first_engine::compose_prompt_packets(&packets)
}

fn runtime_plan_memory_text(plan: &[serde_json::Value]) -> Option<String> {
    if plan.is_empty() {
        return None;
    }
    let done = plan_done_count(plan);
    let total = plan.len();
    let next = plan_next_open(plan);
    let mut parts = vec![format!("Runtime plan state: {done}/{total} steps done.")];
    if plan_is_complete(plan) {
        parts.push("Plan is complete.".to_string());
    } else {
        match next {
            Some(step) => parts.push(format!("Next step: {step}.")),
            None => {
                parts.push("Plan is blocked or unfinished with no runnable next step.".to_string())
            }
        }
    }
    Some(parts.join(" "))
}

fn runtime_plan_memory_metadata(
    thread_id: Option<&str>,
    plan: &[serde_json::Value],
) -> serde_json::Value {
    serde_json::json!({
        "source": "runtime_plan",
        "thread_id": runtime_plan_thread_key(thread_id),
        "status": if plan_is_complete(plan) { "complete" } else { "open" },
        "done_count": plan_done_count(plan),
        "total_count": plan.len(),
        "next_step": plan_next_open(plan),
        "steps": plan,
        "execution_plan": runtime_execution_plan(plan),
    })
}

/// THE shape of `LoopState.plan` — the plan the engine reads: canonical steps
/// (`{id,title,status,detail}`) under `steps`, the same language the merge, the F2 verifier, the
/// persistence (`upsert_runtime_plan_memory_from_state`) and the ‹‹PLAN›› marker already speak.
///
/// It must NEVER be the raw `serde_json::to_value(&ExecutionPlan)`: `PlanStep` keeps title/status
/// inside `arguments`, so the engine's readers (`plan_step_status`/`plan_step_title`, which default
/// to `"todo"`/`""` on a missing field) saw an untitled `todo` for EVERY step whatever its real
/// state. That silently disabled every plan-driven control in the loop — the evidence-driven
/// frontier advance and the "keep going, your next step is X" nudge, i.e. exactly the harness nets
/// that must fire when the model stops calling `step_advance` itself. With no step ever closing,
/// the per-step budgets never reset and elapsed time became the only limit the turn had left.
fn canonical_plan_value(steps: &[serde_json::Value]) -> serde_json::Value {
    serde_json::json!({ "steps": steps })
}

/// The gateway's typed `ExecutionPlan` from `LoopState.plan` (ADR 0024 inc 5, P5). The loop carries
/// the plan in the canonical shape above; the ExecutionPlan-only helpers (`merge_execution_plan`,
/// `plan_steps_reconciled_on_delivery`) still want the typed form, so rebuild it from those steps.
/// Lossless for the chat plan: every step in `ls.plan` was produced by `runtime_execution_plan`, so
/// the orchestrator-only fields (`kind`, `provider_id`, `tool_name`) are already its defaults. An
/// empty plan is the safe fallback for `Null`/malformed, matching the old seed.
fn plan_value_from(plan: &serde_json::Value) -> ExecutionPlan {
    runtime_execution_plan(&plan_value_steps(plan))
}

fn runtime_execution_plan(plan: &[serde_json::Value]) -> ExecutionPlan {
    ExecutionPlan {
        route: OrchestratorRoute::MixedWorkflow,
        direct_answer: None,
        plan_propose: None,
        steps: plan
            .iter()
            .enumerate()
            .filter_map(|(index, step)| {
                let title = plan_step_title(step).trim();
                if title.is_empty() {
                    return None;
                }
                let step_id = plan_step_id(step)
                    .map(str::to_string)
                    .unwrap_or_else(|| format!("s{}", index + 1));
                Some(PlanStep {
                    step_id,
                    kind: PlanStepKind::DirectAnswer,
                    depends_on: plan_step_depends_on(step),
                    provider_id: None,
                    tool_name: None,
                    arguments: serde_json::json!({
                        "title": title,
                        "status": plan_step_status(step),
                        "detail": step.get("detail").cloned().unwrap_or(serde_json::Value::Null),
                        "done_criterion": step
                            .get("done_criterion")
                            .cloned()
                            .unwrap_or(serde_json::Value::Null),
                    }),
                    execution_policy: StepExecutionPolicy::Immediate,
                    risk_level: "low".to_string(),
                    expected_duration_seconds: 0,
                    agent_id: None,
                    goal: Some(title.to_string()),
                    contract: Some("runtime_plan_step".to_string()),
                    allowed_actions: vec![],
                    requires_user_approval: None,
                    timeout_seconds: None,
                    max_tokens: None,
                })
            })
            .collect(),
        needs_more_tools: None,
    }
}

fn execution_plan_steps(plan: &ExecutionPlan) -> Vec<serde_json::Value> {
    plan.steps
        .iter()
        .map(|step| {
            let title = step
                .arguments
                .get("title")
                .and_then(|value| value.as_str())
                .or(step.goal.as_deref())
                .unwrap_or("")
                .to_string();
            serde_json::json!({
                "id": step.step_id,
                "title": title,
                "status": step.arguments
                    .get("status")
                    .and_then(|value| value.as_str())
                    .unwrap_or("todo"),
                "detail": step.arguments
                    .get("detail")
                    .cloned()
                    .unwrap_or(serde_json::Value::Null),
                "done_criterion": step.arguments
                    .get("done_criterion")
                    .cloned()
                    .unwrap_or(serde_json::Value::Null),
                "depends_on": step.depends_on,
            })
        })
        .collect()
}

fn merge_execution_plan(plan: &mut ExecutionPlan, sent: &[serde_json::Value]) -> Vec<usize> {
    let mut steps = execution_plan_steps(plan);
    let claims = merge_plan(&mut steps, sent);
    // Derive completion of earlier steps from the current frontier (see helper) so the
    // persisted plan — and thus every surface that renders it — reflects real progress.
    enforce_monotonic_plan_progress(&mut steps);
    let mut previous_steps = std::mem::take(&mut plan.steps);
    plan.steps = steps
        .iter()
        .filter_map(|step_view| {
            let step_id = plan_step_id(step_view)?.to_string();
            if let Some(index) = previous_steps
                .iter()
                .position(|step| step.step_id == step_id)
            {
                let mut step = previous_steps.remove(index);
                apply_execution_plan_step_view(&mut step, step_view);
                Some(step)
            } else {
                runtime_execution_plan(std::slice::from_ref(step_view))
                    .steps
                    .into_iter()
                    .next()
            }
        })
        .collect();
    claims
}

fn apply_execution_plan_step_view(step: &mut PlanStep, step_view: &serde_json::Value) {
    if !plan_step_depends_on(step_view).is_empty() {
        step.depends_on = plan_step_depends_on(step_view);
    }
    if !step.arguments.is_object() {
        step.arguments = serde_json::json!({});
    }
    if let Some(arguments) = step.arguments.as_object_mut() {
        arguments.insert(
            "title".to_string(),
            serde_json::json!(plan_step_title(step_view)),
        );
        arguments.insert(
            "status".to_string(),
            serde_json::json!(plan_step_status(step_view)),
        );
        arguments.insert(
            "detail".to_string(),
            step_view
                .get("detail")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
        );
        arguments.insert(
            "done_criterion".to_string(),
            step_view
                .get("done_criterion")
                .cloned()
                .unwrap_or(serde_json::Value::Null),
        );
    }
}

